// Broadcastwell Looker Studio connector: field definitions for every data set.
// Plain data plus one builder. The builder is the only part that touches DataStudioApp.
// MIT licence, see LICENSE at the repository root.

var BwSchema = (function () {
  // Each field: [id, name, type, kind, description]
  //   type: TEXT, NUMBER, BOOLEAN, URL or YEAR_MONTH_DAY
  //   kind: 'dim', 'count' (an integer count, summed) or 'rate' (a rate figure, never summed)
  function rateFields(prefix, label) {
    return [
      [prefix + '_pct', label + ' %', 'NUMBER', 'rate', label + ' as a percentage from 0 to 100. Read it with its base and interval.'],
      [prefix + '_low', label + ' 95% low', 'NUMBER', 'rate', 'Lower end of the 95% interval, percentage points.'],
      [prefix + '_high', label + ' 95% high', 'NUMBER', 'rate', 'Upper end of the 95% interval, percentage points.'],
      [prefix + '_interval', label + ' 95% interval', 'TEXT', 'dim', 'The 95% interval as printed, for example 15.9 to 39.6.'],
      [prefix + '_base', label + ' base', 'TEXT', 'dim', 'The count behind the rate, for example 13 of 50 answers.'],
    ];
  }

  function side(prefix, label) {
    return [
      [prefix + '_run_id', label + ' run id', 'TEXT', 'dim', ''],
      [prefix + '_pass_id', label + ' pass id', 'TEXT', 'dim', ''],
      [prefix + '_observed_on', label + ' observed on', 'YEAR_MONTH_DAY', 'dim', ''],
      [prefix + '_named', label + ' named', 'NUMBER', 'count', 'Answers that named the company.'],
      [prefix + '_scored', label + ' scored', 'NUMBER', 'count', 'Answers scored.'],
    ].concat(rateFields(prefix + '_named', label + ' named rate'));
  }

  var DATASETS = {
    history: {
      label: 'History',
      runLevel: false,
      fields: [
        ['scope', 'Scope', 'TEXT', 'dim', 'account, engine or question_type.'],
        ['segment_key', 'Segment key', 'TEXT', 'dim', 'account, an engine id or a question type.'],
        ['segment_label', 'Segment', 'TEXT', 'dim', ''],
        ['engine_id', 'Engine id', 'TEXT', 'dim', 'Filled for the engine scope.'],
        ['engine_label', 'Engine', 'TEXT', 'dim', 'ChatGPT, Claude, Perplexity, Google AI Overviews or Google AI Mode. Filled for the engine scope.'],
        ['run_id', 'Run id', 'TEXT', 'dim', ''],
        ['pass_id', 'Pass id', 'TEXT', 'dim', ''],
        ['pass_kind', 'Pass kind', 'TEXT', 'dim', 'Scheduled passes only. Adaptive passes are never history points.'],
        ['observed_on', 'Observed on', 'YEAR_MONTH_DAY', 'dim', ''],
        ['method_version', 'Method version', 'TEXT', 'dim', ''],
        ['series', 'Series', 'NUMBER', 'dim', 'Points are comparable only within one series.'],
        ['series_label', 'Series label', 'TEXT', 'dim', ''],
        ['movement', 'Movement', 'TEXT', 'dim', 'Moved up or Moved down only where the two 95% intervals separate.'],
        ['method_break_before', 'Method break before', 'BOOLEAN', 'dim', 'True when the method changed before this point.'],
        ['observed', 'Observed', 'NUMBER', 'count', 'Answers observed.'],
        ['excluded', 'Excluded', 'NUMBER', 'count', 'Answers excluded from scoring.'],
        ['named', 'Named', 'NUMBER', 'count', 'Answers that named the company.'],
        ['scored', 'Scored', 'NUMBER', 'count', 'Answers scored.'],
      ].concat(rateFields('named', 'Named rate')),
    },
    summary: {
      label: 'Run summary',
      runLevel: true,
      fields: [
        ['run_id', 'Run id', 'TEXT', 'dim', ''],
        ['run_kind', 'Run kind', 'TEXT', 'dim', ''],
        ['method_version', 'Method version', 'TEXT', 'dim', ''],
        ['pass_group', 'Pass group', 'TEXT', 'dim', 'Scheduled, or Adaptive (shown separately). Headline figures are scheduled only.'],
        ['segment_type', 'Segment type', 'TEXT', 'dim', 'overall, engine, question_type or adaptive. Filter to one type before adding counts.'],
        ['segment_key', 'Segment key', 'TEXT', 'dim', ''],
        ['segment_label', 'Segment', 'TEXT', 'dim', ''],
        ['engine_id', 'Engine id', 'TEXT', 'dim', ''],
        ['engine_label', 'Engine', 'TEXT', 'dim', ''],
        ['question_count', 'Questions in run', 'NUMBER', 'count', ''],
        ['observed', 'Observed', 'NUMBER', 'count', ''],
        ['scored', 'Scored', 'NUMBER', 'count', ''],
        ['excluded', 'Excluded', 'NUMBER', 'count', ''],
        ['named', 'Named', 'NUMBER', 'count', 'Answers that named the company.'],
      ].concat(rateFields('named', 'Named rate'), [
        ['own_domain_cited', 'Own domain cited', 'NUMBER', 'count', 'Answers that cited the company domain.'],
      ], rateFields('cited', 'Own domain cited rate'), [
        ['questions_with_a_mention', 'Questions with a mention', 'NUMBER', 'count', 'Overall row only.'],
        ['questions_total', 'Questions counted', 'NUMBER', 'count', 'Overall row only.'],
      ]),
    },
    displacement: {
      label: 'Named instead',
      runLevel: true,
      fields: [
        ['run_id', 'Run id', 'TEXT', 'dim', ''],
        ['question_id', 'Question id', 'NUMBER', 'dim', ''],
        ['question_text', 'Question', 'TEXT', 'dim', ''],
        ['question_type', 'Question type', 'TEXT', 'dim', ''],
        ['checklist', 'Checklist', 'TEXT', 'dim', ''],
        ['competitor', 'Competitor', 'TEXT', 'dim', ''],
        ['competitor_status', 'Competitor status', 'TEXT', 'dim', 'Named, or Checked, not found.'],
        ['question_scored', 'Question answers scored', 'NUMBER', 'count', 'Repeats on every competitor row of the question. Use MAX, not SUM, across competitors.'],
        ['client_named', 'Answers naming the company', 'NUMBER', 'count', 'Repeats on every competitor row of the question.'],
        ['client_absent', 'Answers without the company', 'NUMBER', 'count', 'Repeats on every competitor row of the question.'],
        ['competitor_checked_in', 'Competitor checked in', 'NUMBER', 'count', 'Answers checked for this competitor.'],
        ['competitor_named', 'Competitor named', 'NUMBER', 'count', 'Answers that named this competitor.'],
        ['competitor_named_instead', 'Competitor named instead', 'NUMBER', 'count', 'Answers that named this competitor and not the company.'],
      ],
    },
    sources: {
      label: 'Sources',
      runLevel: true,
      fields: [
        ['run_id', 'Run id', 'TEXT', 'dim', ''],
        ['url', 'Cited page', 'URL', 'dim', ''],
        ['domain', 'Domain', 'TEXT', 'dim', ''],
        ['own_domain', 'Own domain', 'BOOLEAN', 'dim', 'True when the page is on the company domain.'],
        ['engine_ids', 'Engine ids', 'TEXT', 'dim', ''],
        ['engine_labels', 'Engines', 'TEXT', 'dim', 'Engines that cited the page.'],
        ['question_ids', 'Question ids', 'TEXT', 'dim', ''],
        ['times_cited', 'Times cited', 'NUMBER', 'count', 'Scheduled answers that cited the page.'],
        ['engine_count', 'Engine count', 'NUMBER', 'count', ''],
        ['question_count', 'Question count', 'NUMBER', 'count', ''],
        ['answers_naming_client', 'Answers naming the company', 'NUMBER', 'count', 'Answers citing the page that also named the company.'],
        ['receipt_count', 'Receipts', 'NUMBER', 'count', ''],
      ],
    },
    alerts: {
      label: 'Alerts',
      runLevel: false,
      fields: [
        ['alert_id', 'Alert id', 'TEXT', 'dim', ''],
        ['rule', 'Rule', 'TEXT', 'dim', ''],
        ['scope', 'Scope', 'TEXT', 'dim', ''],
        ['segment_key', 'Segment key', 'TEXT', 'dim', ''],
        ['segment_label', 'Segment', 'TEXT', 'dim', ''],
        ['engine_label', 'Engine', 'TEXT', 'dim', 'Filled for engine alerts.'],
        ['direction', 'Direction', 'TEXT', 'dim', 'up or down.'],
        ['observed_on', 'Observed on', 'YEAR_MONTH_DAY', 'dim', ''],
        ['statement', 'Statement', 'TEXT', 'dim', ''],
        ['receipts_api_url', 'Receipts API link', 'URL', 'dim', 'API address of the receipts for the later pass. Needs your key.'],
      ].concat(side('from', 'From'), side('to', 'To')),
    },
  };

  var ORDER = ['history', 'summary', 'displacement', 'sources', 'alerts'];

  function dataset(id) {
    return Object.prototype.hasOwnProperty.call(DATASETS, id) ? DATASETS[id] : null;
  }

  function fieldIds(id) {
    var d = dataset(id);
    return d ? d.fields.map(function (f) { return f[0]; }) : [];
  }

  function fieldTypes(id) {
    var out = {};
    var d = dataset(id);
    if (d) d.fields.forEach(function (f) { out[f[0]] = f[2]; });
    return out;
  }

  // Builds a DataStudioApp Fields object for one data set.
  function buildFields(cc, id) {
    var d = dataset(id);
    var fields = cc.getFields();
    var types = cc.FieldType;
    var agg = cc.AggregationType;
    d.fields.forEach(function (f) {
      var field = f[3] === 'dim' ? fields.newDimension() : fields.newMetric();
      field.setId(f[0]).setName(f[1]).setType(types[f[2]]);
      if (f[4]) field.setDescription(f[4]);
      if (f[3] === 'count') field.setAggregation(agg.SUM);
      if (f[3] === 'rate') field.setAggregation(agg.NO_AGGREGATION);
    });
    return fields;
  }

  return {
    DATASETS: DATASETS,
    ORDER: ORDER,
    dataset: dataset,
    fieldIds: fieldIds,
    fieldTypes: fieldTypes,
    buildFields: buildFields,
  };
})();

// ===== src/Mapping.js =====
// Broadcastwell Looker Studio connector: API JSON to rows.
// Pure functions with no Apps Script services, so the tests run them in Node.
// Numbers pass through exactly as the API sends them. Every rate becomes five
// columns (pct, low, high, interval, base) next to its integer counts.
// MIT licence, see LICENSE at the repository root.

var BwMap = (function () {
  function engineLabel(id) {
    var labels = BroadcastwellRoutes.ENGINES;
    return id && Object.prototype.hasOwnProperty.call(labels, id) ? labels[id] : '';
  }

  function num(value) {
    return typeof value === 'number' && isFinite(value) ? value : null;
  }

  function text(value) {
    return value === undefined || value === null ? '' : String(value);
  }

  // '2026-07-12' or '2026-07-12T08:03:00.000Z' to '20260712' (YEAR_MONTH_DAY).
  function ymd(value) {
    var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(text(value));
    return m ? m[1] + m[2] + m[3] : null;
  }

  // Splits a rate object {pct, low, high, interval, base} into five columns.
  function splitRate(row, prefix, rate) {
    var r = rate && typeof rate === 'object' ? rate : {};
    row[prefix + '_pct'] = num(r.pct);
    row[prefix + '_low'] = num(r.low);
    row[prefix + '_high'] = num(r.high);
    row[prefix + '_interval'] = text(r.interval);
    row[prefix + '_base'] = text(r.base);
    return row;
  }

  // History: GET /accounts/{account}/history. One row per point.
  function history(body) {
    var rows = [];
    var segments = body && Array.isArray(body.data) ? body.data : [];
    segments.forEach(function (seg) {
      var seriesLabels = {};
      (seg.series || []).forEach(function (s) { seriesLabels[s.series] = s.label; });
      var moves = {};
      var breaks = {};
      (seg.steps || []).forEach(function (step) {
        if (step.type === 'comparison' && step.to) {
          moves[step.to.run_id + '/' + step.to.pass_id] = step.label;
        } else if (step.type === 'method_break') {
          breaks[step.after] = true;
        }
      });
      var isEngine = seg.scope === 'engine';
      (seg.points || []).forEach(function (p) {
        var row = {
          scope: text(seg.scope),
          segment_key: text(seg.key),
          segment_label: text(seg.label),
          engine_id: isEngine ? text(seg.key) : '',
          engine_label: isEngine ? engineLabel(seg.key) || text(seg.label) : '',
          run_id: text(p.run_id),
          pass_id: text(p.pass_id),
          pass_kind: text(p.pass_kind),
          observed_on: ymd(p.observed_on),
          method_version: text(p.method_version),
          series: num(p.series),
          series_label: text(seriesLabels[p.series]),
          movement: text(moves[p.run_id + '/' + p.pass_id]),
          method_break_before: breaks[p.pass_id] === true,
          observed: num(p.observed),
          excluded: num(p.excluded),
          named: num(p.named),
          scored: num(p.scored),
        };
        rows.push(splitRate(row, 'named', p.named_rate));
      });
    });
    return rows;
  }

  function summaryRow(base, group, type, key, label, block) {
    var row = {
      run_id: base.run_id,
      run_kind: base.run_kind,
      method_version: base.method_version,
      question_count: base.question_count,
      pass_group: group,
      segment_type: type,
      segment_key: key,
      segment_label: label,
      engine_id: type === 'engine' ? key : '',
      engine_label: type === 'engine' ? engineLabel(key) || label : '',
      observed: num(block.observed),
      scored: num(block.scored),
      excluded: num(block.excluded),
      named: num(block.named),
      own_domain_cited: num(block.own_domain_cited),
      questions_with_a_mention: null,
      questions_total: null,
    };
    splitRate(row, 'named', block.named_rate);
    splitRate(row, 'cited', block.cited_rate);
    return row;
  }

  // Run summary: GET /accounts/{account}/runs/{run}/summary.
  // Rows: overall, one per engine, one per question type, all from scheduled passes.
  // The adaptive block is never added in. With includeAdaptive it becomes its own
  // row, pass group "Adaptive (shown separately)".
  function summary(body, includeAdaptive) {
    var d = body && body.data ? body.data : {};
    var s = d.scheduled || {};
    var base = {
      run_id: text(d.run_id),
      run_kind: text(d.kind),
      method_version: text(d.method_version),
      question_count: num(d.question_count),
    };
    var rows = [];
    var overall = summaryRow(base, 'Scheduled', 'overall', 'overall', 'All questions and engines', s);
    if (s.questions_with_a_mention) {
      overall.questions_with_a_mention = num(s.questions_with_a_mention.count);
      overall.questions_total = num(s.questions_with_a_mention.of);
    }
    rows.push(overall);
    var engines = s.per_engine || {};
    var order = BroadcastwellRoutes.ENGINE_IDS.filter(function (id) { return engines[id]; });
    Object.keys(engines).forEach(function (id) { if (order.indexOf(id) < 0) order.push(id); });
    order.forEach(function (id) {
      rows.push(summaryRow(base, 'Scheduled', 'engine', id, text(engines[id].label), engines[id]));
    });
    var types = s.per_question_type || {};
    Object.keys(types).forEach(function (key) {
      rows.push(summaryRow(base, 'Scheduled', 'question_type', key, text(types[key].label), types[key]));
    });
    if (includeAdaptive && d.adaptive) {
      rows.push(summaryRow(base, 'Adaptive (shown separately)', 'adaptive', 'adaptive', text(d.adaptive.label), d.adaptive));
    }
    return rows;
  }

  var STATUS_LABELS = { named: 'Named', checked_not_found: 'Checked, not found' };

  // Named instead: items from GET /accounts/{account}/runs/{run}/displacement.
  // One row per question and competitor.
  function displacement(items, runId) {
    var rows = [];
    (items || []).forEach(function (q) {
      var common = {
        run_id: text(runId),
        question_id: num(q.question_id),
        question_text: text(q.question_text),
        question_type: text(q.question_type),
        checklist: text(q.checklist),
        question_scored: num(q.scored),
        client_named: num(q.client_named),
        client_absent: num(q.client_absent),
      };
      var competitors = q.competitors && q.competitors.length ? q.competitors : [null];
      competitors.forEach(function (c) {
        var row = Object.assign({}, common);
        row.competitor = c ? text(c.name) : '';
        row.competitor_status = c ? text(STATUS_LABELS[c.status] || c.status) : '';
        row.competitor_checked_in = c ? num(c.checked_in) : null;
        row.competitor_named = c ? num(c.named) : null;
        row.competitor_named_instead = c ? num(c.named_instead) : null;
        rows.push(row);
      });
    });
    return rows;
  }

  // Sources: items from GET /accounts/{account}/runs/{run}/sources. One row per cited page.
  function sources(items, runId) {
    return (items || []).map(function (s) {
      var engines = Array.isArray(s.engines) ? s.engines : [];
      var questions = Array.isArray(s.question_ids) ? s.question_ids : [];
      return {
        run_id: text(runId),
        url: text(s.url),
        domain: text(s.domain),
        own_domain: s.own_domain === true,
        engine_ids: engines.map(function (e) { return e.id; }).join(', '),
        engine_labels: engines.map(function (e) { return engineLabel(e.id) || e.label; }).join(', '),
        question_ids: questions.join(', '),
        times_cited: num(s.times_cited),
        engine_count: engines.length,
        question_count: questions.length,
        answers_naming_client: num(s.answers_naming_client),
        receipt_count: Array.isArray(s.receipt_ids) ? s.receipt_ids.length : null,
      };
    });
  }

  function alertSide(row, prefix, side) {
    var s = side || {};
    row[prefix + '_run_id'] = text(s.run_id);
    row[prefix + '_pass_id'] = text(s.pass_id);
    row[prefix + '_observed_on'] = ymd(s.observed_on);
    row[prefix + '_named'] = num(s.named);
    row[prefix + '_scored'] = num(s.scored);
    splitRate(row, prefix + '_named', s.named_rate);
  }

  // Alerts: items from GET /accounts/{account}/alerts. One row per alert.
  function alerts(items) {
    return (items || []).map(function (a) {
      var row = {
        alert_id: text(a.alert_id),
        rule: text(a.rule),
        scope: text(a.scope),
        segment_key: text(a.key),
        segment_label: text(a.label),
        engine_label: a.scope === 'engine' ? engineLabel(a.key) || text(a.label) : '',
        direction: text(a.direction),
        observed_on: ymd(a.observed_on),
        statement: text(a.statement),
        receipts_api_url: a.links && a.links.receipts ? text(a.links.receipts) : '',
      };
      alertSide(row, 'from', a.from);
      alertSide(row, 'to', a.to);
      return row;
    });
  }

  // Picks the newest delivered run that has at least one scheduled pass.
  function latestRunId(runs) {
    var best = null;
    (runs || []).forEach(function (r) {
      var scheduled = (r.passes || []).some(function (p) { return p.scheduled === true; });
      if (!scheduled || (r.status && r.status !== 'delivered')) return;
      var when = text(r.completed_at || r.created_at);
      if (!best || when > best.when) best = { id: r.run_id, when: when };
    });
    return best ? best.id : null;
  }

  // Turns row objects into Looker Studio rows holding only the requested fields, in order.
  function toValues(rows, ids, types) {
    return rows.map(function (row) {
      return {
        values: ids.map(function (id) {
          var v = row[id];
          var t = types ? types[id] : undefined;
          if (v === undefined || v === null) return t === 'NUMBER' || t === 'YEAR_MONTH_DAY' ? null : t === 'BOOLEAN' ? false : '';
          return v;
        }),
      };
    });
  }

  return {
    engineLabel: engineLabel,
    ymd: ymd,
    splitRate: splitRate,
    history: history,
    summary: summary,
    displacement: displacement,
    sources: sources,
    alerts: alerts,
    latestRunId: latestRunId,
    toValues: toValues,
  };
})();

// ===== src/Api.js =====
// Broadcastwell Looker Studio connector: a synchronous caller over UrlFetchApp.
//
// Routes, path building and query building come from packages/api through the
// generated BroadcastwellRoutes block (see scripts/build.mjs), so this file never
// spells a route. It does not use createClient() from packages/api because that
// client is Promise based: Looker Studio calls getData() and needs the rows as the
// return value, and no Apps Script documentation says an entry point may return a
// Promise. UrlFetchApp is synchronous, so a plain synchronous caller is simpler and
// certain.
// MIT licence, see LICENSE at the repository root.

var BwApi = (function () {
  var R = BroadcastwellRoutes;
  var CACHE_SECONDS = 300;
  var CACHE_MAX_CHARS = 90000;
  var MAX_PAGES = 50;
  var MAX_RETRY_WAIT_SECONDS = 5;

  function HttpError(status, code, detail, retryAfter, url) {
    this.name = 'BroadcastwellHttpError';
    this.status = status;
    this.code = code || (status ? 'http_' + status : 'network_error');
    this.detail = detail || '';
    this.retryAfter = retryAfter;
    this.url = url;
    this.message = 'Broadcastwell API ' + status + ' ' + this.code + ': ' + this.detail;
  }
  HttpError.prototype = Object.create(Error.prototype);
  HttpError.prototype.constructor = HttpError;

  // A key is bwp_ followed by 64 hex characters, or the public demo key.
  function looksLikeKey(key) {
    return typeof key === 'string' && (key === R.DEMO_KEY || /^bwp_[0-9a-fA-F]{64}$/.test(key));
  }

  // "me" (or blank) reads your own account. The demo key reads only the sample,
  // so with the demo key "me" becomes "sample", as createClient() does in packages/api.
  function accountFor(apiKey, account) {
    var a = String(account === undefined || account === null ? '' : account).trim();
    if (!a || a === 'me') return apiKey === R.DEMO_KEY ? R.SAMPLE_ACCOUNT : 'me';
    return a;
  }

  function urlFor(name, params) {
    var route = R.routes[name];
    if (!route) throw new TypeError('Unknown Broadcastwell route: ' + name);
    return R.DEFAULT_BASE_URL + R.buildPath(route, params) + R.buildQuery(route, params);
  }

  function lowerHeaders(headers) {
    var out = {};
    Object.keys(headers || {}).forEach(function (k) { out[k.toLowerCase()] = headers[k]; });
    return out;
  }

  function cacheKey(apiKey, url) {
    var bytes = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, apiKey + '\n' + url);
    var hex = '';
    for (var i = 0; i < bytes.length; i++) {
      var b = (bytes[i] + 256) % 256;
      hex += (b < 16 ? '0' : '') + b.toString(16);
    }
    return 'bw1:' + hex;
  }

  function userCache() {
    try {
      return CacheService.getUserCache();
    } catch (e) {
      return null;
    }
  }

  function fetchOnce(apiKey, url) {
    var response;
    try {
      response = UrlFetchApp.fetch(url, {
        method: 'get',
        muteHttpExceptions: true,
        followRedirects: false,
        headers: { Authorization: 'Bearer ' + apiKey, Accept: 'application/json' },
      });
    } catch (e) {
      throw new HttpError(0, 'network_error', 'Could not reach the Broadcastwell API: ' + (e && e.message ? e.message : String(e)), null, url);
    }
    return {
      status: response.getResponseCode(),
      headers: lowerHeaders(response.getHeaders()),
      text: response.getContentText(),
    };
  }

  function parse(text) {
    try {
      return text ? JSON.parse(text) : null;
    } catch (e) {
      return null;
    }
  }

  // GET one route. Returns the parsed JSON body or throws HttpError.
  // Successful answers are cached per key and address for five minutes, because
  // Looker Studio calls getData once per chart and the demo key allows 30 requests a minute.
  function getJson(apiKey, name, params, options) {
    var o = options || {};
    var url = urlFor(name, params);
    var cache = o.cache === false ? null : userCache();
    var key = cache ? cacheKey(apiKey, url) : null;
    if (cache) {
      var hit = cache.get(key);
      if (hit) {
        var cached = parse(hit);
        if (cached !== null) return cached;
      }
    }
    var res = fetchOnce(apiKey, url);
    if (res.status === 429) {
      var wait = Number(res.headers['retry-after']);
      if (isFinite(wait) && wait >= 0 && wait <= MAX_RETRY_WAIT_SECONDS) {
        Utilities.sleep(Math.max(1, wait) * 1000);
        res = fetchOnce(apiKey, url);
      }
    }
    var body = parse(res.text);
    if (res.status < 200 || res.status >= 300) {
      var problem = body && typeof body === 'object' ? body : {};
      var retryAfter = Number(res.headers['retry-after']);
      throw new HttpError(res.status, problem.code, problem.detail || problem.title || '', isFinite(retryAfter) ? retryAfter : null, url);
    }
    if (body === null) throw new HttpError(res.status, 'bad_response', 'The answer was not JSON.', null, url);
    if (cache && res.text.length <= CACHE_MAX_CHARS) {
      try {
        cache.put(key, res.text, CACHE_SECONDS);
      } catch (e) {
        // A full cache is not an error.
      }
    }
    return body;
  }

  // GET every page of a paged route, following pagination.next_cursor.
  // Returns { items, pages, first } where first is the first page body.
  function getAll(apiKey, name, params, options) {
    if (!R.routes[name] || !R.routes[name].paged) throw new TypeError(name + ' does not page.');
    var items = [];
    var seen = {};
    var cursor;
    var first = null;
    var pages = 0;
    for (;;) {
      var p = Object.assign({}, params, { limit: 100, cursor: cursor });
      var page = getJson(apiKey, name, p, options);
      pages++;
      if (!first) first = page;
      var data = page && Array.isArray(page.data) ? page.data : [];
      for (var i = 0; i < data.length; i++) items.push(data[i]);
      var next = page && page.pagination ? page.pagination.next_cursor : null;
      if (!next || seen[next] || data.length === 0 || pages >= MAX_PAGES) break;
      seen[next] = true;
      cursor = next;
    }
    return { items: items, pages: pages, first: first };
  }

  return {
    HttpError: HttpError,
    looksLikeKey: looksLikeKey,
    accountFor: accountFor,
    urlFor: urlFor,
    getJson: getJson,
    getAll: getAll,
  };
})();

// ===== src/Code.js =====
// Broadcastwell Looker Studio connector: the functions Looker Studio calls.
// getAuthType, setCredentials, isAuthValid, resetAuth, getConfig, getSchema, getData.
// MIT licence, see LICENSE at the repository root.

var cc = DataStudioApp.createCommunityConnector();
var BW_KEY_PROPERTY = 'dscc.key';
var BW_HELP_URL = 'https://app.broadcastwell.com/developers';

// ---------------------------------------------------------------------------
// Auth: an API key, stored in this user's UserProperties
// ---------------------------------------------------------------------------

function getAuthType() {
  return cc.newAuthTypeResponse().setAuthType(cc.AuthType.KEY).setHelpUrl(BW_HELP_URL).build();
}

function bwStoredKey_() {
  return PropertiesService.getUserProperties().getProperty(BW_KEY_PROPERTY);
}

// True when GET /me accepts the key. Only a 401 or 403 means the key is wrong;
// other failures are reported by getData with their own message.
function bwKeyAccepted_(key, useCache) {
  try {
    BwApi.getJson(key, 'getMe', {}, { cache: useCache });
    return true;
  } catch (e) {
    if (e instanceof BwApi.HttpError && (e.status === 401 || e.status === 403)) return false;
    if (useCache) return true;
    return false;
  }
}

function setCredentials(request) {
  var key = request && typeof request.key === 'string' ? request.key.trim() : '';
  if (!BwApi.looksLikeKey(key) || !bwKeyAccepted_(key, false)) {
    return { errorCode: 'INVALID_CREDENTIALS' };
  }
  PropertiesService.getUserProperties().setProperty(BW_KEY_PROPERTY, key);
  return { errorCode: 'NONE' };
}

function isAuthValid() {
  var key = bwStoredKey_();
  if (!key || !BwApi.looksLikeKey(key)) return false;
  return bwKeyAccepted_(key, true);
}

function resetAuth() {
  PropertiesService.getUserProperties().deleteProperty(BW_KEY_PROPERTY);
}

function isAdminUser() {
  return false;
}

// ---------------------------------------------------------------------------
// Errors people can act on
// ---------------------------------------------------------------------------

var BW_DEMO_HINT = 'The public demo key ' + BroadcastwellRoutes.DEMO_KEY + ' reads the fictional Kalvenor sample, account sample.';

function bwUserMessage_(e) {
  if (e && typeof e.bwMessage === 'string') return e.bwMessage;
  if (!(e instanceof BwApi.HttpError)) {
    return 'The Broadcastwell connector hit an unexpected problem. Refresh the data source, and if it happens again write to hello@broadcastwell.com with the time it happened.';
  }
  var detail = e.detail ? ' Broadcastwell says: ' + e.detail : '';
  switch (e.status) {
    case 0:
      return 'Looker Studio could not reach the Broadcastwell API. Try again in a minute.' + detail;
    case 400:
      return 'Broadcastwell did not accept a setting of this data source. Edit the connection and check the account and run.' + detail;
    case 401:
      return 'Broadcastwell did not accept the API key. Revoke access to this connector, then add it again with a key from app.broadcastwell.com/account. ' + BW_DEMO_HINT;
    case 403:
      return 'This API key cannot read that account. Leave Account as me to read your own account. ' + BW_DEMO_HINT;
    case 404:
      return 'No account or run with that id is available to this key. Leave Account as me for your own account, and pick a run from the list or choose Latest run. ' + BW_DEMO_HINT + detail;
    case 409:
      return 'Broadcastwell cannot return this data yet, usually because the run is still being measured. Try again once the run is delivered, or choose Latest run.' + detail;
    case 429:
      var wait = e.retryAfter ? ' Wait ' + e.retryAfter + ' seconds, then refresh the report.' : ' Wait a minute, then refresh the report.';
      return 'Too many requests to the Broadcastwell API.' + wait + ' The demo key allows 30 requests a minute; your own key allows more.';
    default:
      if (e.status >= 500) return 'The Broadcastwell API did not answer this time. Try again in a minute.' + detail;
      return 'The Broadcastwell API answered with status ' + e.status + '.' + detail;
  }
}

function bwThrow_(e) {
  cc.newUserError()
    .setDebugText(String(e && e.message ? e.message : e))
    .setText(bwUserMessage_(e))
    .throwException();
}

function bwRequireKey_() {
  var key = bwStoredKey_();
  if (!key) {
    cc.newUserError()
      .setDebugText('No API key stored')
      .setText('Add your Broadcastwell API key to use this connector. ' + BW_DEMO_HINT)
      .throwException();
  }
  return key;
}

// ---------------------------------------------------------------------------
// Config: stepped. Step 1 asks for the account and the data set. Step 2 asks what
// that data set needs: a history scope, or a run picked from the account's runs.
// ---------------------------------------------------------------------------

var BW_LATEST = 'latest';

function bwRunOptions_(key, account) {
  var list = BwApi.getAll(key, 'listRuns', { account: account }).items;
  return list.map(function (r) {
    var scheduled = (r.passes || []).filter(function (p) { return p.scheduled === true; }).length;
    var when = r.completed_at ? String(r.completed_at).slice(0, 10) : 'not completed';
    return {
      label: r.run_id + ' (' + r.kind + ', ' + scheduled + (scheduled === 1 ? ' scheduled pass, ' : ' scheduled passes, ') + when + ')',
      value: r.run_id,
    };
  });
}

function getConfig(request) {
  var params = (request && request.configParams) || {};
  var config = cc.getConfig();

  config
    .newInfo()
    .setId('intro')
    .setText('Broadcastwell measures whether ChatGPT, Claude, Perplexity, Google AI Overviews and Google AI Mode name your company when buyers ask shortlist questions. Figures come from scheduled passes; adaptive answers are kept apart. Every rate arrives as five columns: percentage, 95% low, 95% high, interval and base, next to its counts.');

  config
    .newTextInput()
    .setId('account')
    .setName('Account')
    .setHelpText('Leave blank or enter me to read your own account. With the public demo key, me reads the fictional Kalvenor sample (account sample).')
    .setPlaceholder('me')
    .setIsDynamic(true);

  var dataset = config
    .newSelectSingle()
    .setId('dataset')
    .setName('Data set')
    .setHelpText('History and Alerts cover every scheduled run. Run summary, Named instead and Sources read one run.')
    .setIsDynamic(true);
  dataset.addOption(config.newOptionBuilder().setLabel('History: one point per scheduled run').setValue('history'));
  dataset.addOption(config.newOptionBuilder().setLabel('Run summary: overall, per engine, per question type').setValue('summary'));
  dataset.addOption(config.newOptionBuilder().setLabel('Named instead: competitors per question').setValue('displacement'));
  dataset.addOption(config.newOptionBuilder().setLabel('Sources: pages cited in scheduled answers').setValue('sources'));
  dataset.addOption(config.newOptionBuilder().setLabel('Alerts: movements where intervals separate').setValue('alerts'));

  var chosen = BwSchema.dataset(params.dataset);
  if (!chosen) {
    config.setIsSteppedConfig(true);
    return config.build();
  }

  if (params.dataset === 'history') {
    var scope = config
      .newSelectSingle()
      .setId('history_scope')
      .setName('History scope')
      .setHelpText('One series for the account, one per engine, or one per question type. Blank means account.')
      .setAllowOverride(true);
    scope.addOption(config.newOptionBuilder().setLabel('Account: all questions and engines').setValue('account'));
    scope.addOption(config.newOptionBuilder().setLabel('Engine: ChatGPT, Claude, Perplexity, Google AI Overviews, Google AI Mode').setValue('engine'));
    scope.addOption(config.newOptionBuilder().setLabel('Question type').setValue('question_type'));
  }

  if (chosen.runLevel) {
    var key = bwRequireKey_();
    var options;
    try {
      options = bwRunOptions_(key, BwApi.accountFor(key, params.account));
    } catch (e) {
      bwThrow_(e);
    }
    var run = config
      .newSelectSingle()
      .setId('run_id')
      .setName('Run')
      .setHelpText('Latest run follows the newest delivered run with scheduled passes, so the report moves on when a new run lands. Blank means Latest run.')
      .setAllowOverride(true);
    run.addOption(config.newOptionBuilder().setLabel('Latest run').setValue(BW_LATEST));
    options.forEach(function (o) {
      run.addOption(config.newOptionBuilder().setLabel(o.label).setValue(o.value));
    });
  }

  if (params.dataset === 'summary') {
    config
      .newCheckbox()
      .setId('include_adaptive')
      .setName('Add the adaptive block as its own row')
      .setHelpText('Adaptive answers re-ask pairs whose scheduled verdicts disagreed. They are never added into the scheduled figures; ticked, they appear as one extra row with pass group Adaptive (shown separately).');
  }

  config.setIsSteppedConfig(false);
  return config.build();
}

// ---------------------------------------------------------------------------
// Schema and data
// ---------------------------------------------------------------------------

function bwDatasetOrThrow_(params) {
  var id = params && params.dataset;
  if (!BwSchema.dataset(id)) {
    cc.newUserError()
      .setDebugText('Unknown data set: ' + id)
      .setText('Choose a data set in the connection settings: History, Run summary, Named instead, Sources or Alerts.')
      .throwException();
  }
  return id;
}

function getSchema(request) {
  var params = (request && request.configParams) || {};
  var id = bwDatasetOrThrow_(params);
  return { schema: BwSchema.buildFields(cc, id).build() };
}

function bwResolveRun_(key, account, runId) {
  var wanted = String(runId || '').trim();
  if (wanted && wanted !== BW_LATEST) return wanted;
  var runs = BwApi.getAll(key, 'listRuns', { account: account }).items;
  var latest = BwMap.latestRunId(runs);
  if (!latest) {
    var err = new Error('No delivered run with scheduled passes');
    err.bwMessage = 'This account has no delivered run with scheduled passes yet, so there is nothing to show for Latest run.';
    throw err;
  }
  return latest;
}

// Fetches and maps the rows for one data set. Returns an array of row objects.
function bwRows_(key, params) {
  var dataset = params.dataset;
  var account = BwApi.accountFor(key, params.account);
  if (dataset === 'history') {
    var scope = params.history_scope || 'account';
    return BwMap.history(BwApi.getJson(key, 'getHistory', { account: account, scope: scope }));
  }
  if (dataset === 'alerts') {
    return BwMap.alerts(BwApi.getAll(key, 'listAlerts', { account: account }).items);
  }
  var run = bwResolveRun_(key, account, params.run_id);
  if (dataset === 'summary') {
    var include = params.include_adaptive === true || params.include_adaptive === 'true';
    return BwMap.summary(BwApi.getJson(key, 'getRunSummary', { account: account, run: run }), include);
  }
  if (dataset === 'displacement') {
    return BwMap.displacement(BwApi.getAll(key, 'listDisplacement', { account: account, run: run }).items, run);
  }
  return BwMap.sources(BwApi.getAll(key, 'listSources', { account: account, run: run }).items, run);
}

function getData(request) {
  var params = (request && request.configParams) || {};
  var id = bwDatasetOrThrow_(params);
  var key = bwRequireKey_();
  var requestedIds = (request.fields || []).map(function (f) { return f.name; });
  var requested = BwSchema.buildFields(cc, id).forIds(requestedIds);
  var ids = requested.asArray().map(function (f) { return f.getId(); });
  var rows;
  try {
    rows = bwRows_(key, params);
  } catch (e) {
    bwThrow_(e);
  }
  return {
    schema: requested.build(),
    rows: BwMap.toValues(rows, ids, BwSchema.fieldTypes(id)),
  };
}
